WF.exportImport=function(){const MAX_PROGRESS_ENTRIES=5e4;function isValidPayload(payload){if(!payload||"object"!=typeof payload||Array.isArray(payload))return!1;const progress=payload.progress;if(!progress||"object"!=typeof progress||Array.isArray(progress))return!1;const keys=Object.keys(progress);return!(keys.length>MAX_PROGRESS_ENTRIES)&&keys.every((key=>"boolean"==typeof progress[key]))}return{exportToFile:function(){const options=WF.options.load(),payload={schema_version:WF.SCHEMA_VERSION,exported_at:(new Date).toISOString(),progress:WF.storage.loadForSync()};if(options.includeOptionsInExport){const exportedOptions={...options};options.includeSyncKeyInExport||delete exportedOptions.syncKey,payload.options=exportedOptions}const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),link=Object.assign(document.createElement("a"),{href:url,download:`wf-checklist-${(new Date).toISOString().slice(0,10)}.json`});document.body.appendChild(link),link.click(),link.remove(),setTimeout((()=>URL.revokeObjectURL(url)),0)},importFromFile:async function(file){const text=await file.text(),payload=JSON.parse(text);if(!isValidPayload(payload))throw new Error("Invalid payload format");payload.schema_version>=WF.SCHEMA_VERSION&&(WF.toast.show("Imported file come from a higher version and is not compatible with this version, please update.",{type:"error",timeoutMs:5e3}),console.warn(`Imported file schema version (${payload.schema_version}) differs from expected (${WF.SCHEMA_VERSION}).`)),WF.storage.save(payload.progress),payload.options&&"object"==typeof payload.options&&WF.options.save({...WF.options.load(),...payload.options})},isValidPayload:isValidPayload}}();